 "content": "from collections import deque


def transform(grid):
    """Encode the number of disconnected 3- and 2-colored objects in 2x3."""
    rows, cols = len(grid), len(grid[0])
    seen = set()
    counts = {3: 0, 2: 0}

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color not in counts or (r, c) in seen:
                continue
            counts[color] += 1
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                cr, cc = q.popleft()
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < rows and 0 <= nc < cols and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))

    encoded = [3] * counts[3] + [2] * counts[2]
    encoded = (encoded + [0] * 6)[:6]
    return [encoded[:3], encoded[3:]]
